"""Intent tests for M1-T15: the table-based value learner (TC-12, TC-13, AGENT-01, AGENT-02, ABL-03)."""

import json
from pathlib import Path
from typing import Any

import numpy as np
import pytest

from rllab.agents import TabularAgent
from rllab.core import AgentParams, Exploration, Transition

ROOT = Path(__file__).resolve().parents[3]
TC12 = ROOT / "tests" / "fixtures" / "rllab" / "TC-12"
TC13 = ROOT / "tests" / "fixtures" / "rllab" / "TC-13"
CONTRACTS = ROOT / "tests" / "contracts"
TABULAR_SAMPLE = CONTRACTS / "agents.TabularAgent" / "samples" / "corridor.json"
PARAMS_SAMPLE = CONTRACTS / "core.AgentParams" / "samples" / "tabular.json"
EXPLORATION_SAMPLE = CONTRACTS / "core.Exploration" / "samples" / "defaults.json"

N_CELLS = 10
N_ACTIONS = 2


def _load(path: Path) -> Any:
    return json.loads(path.read_text())


def _array(spec: dict[str, Any]) -> np.ndarray:
    return np.asarray(spec["data"], dtype=spec["dtype"]).reshape(spec["shape"])


def _cell(index: int) -> np.ndarray:
    obs = np.zeros((1, N_CELLS), dtype=np.float32)
    obs[0, index] = 1.0
    return obs


def _transition(
    cell: int,
    action: int,
    reward: float,
    next_cell: int,
    *,
    terminated: bool,
    truncated: bool = False,
) -> Transition:
    return Transition(
        obs=_cell(cell),
        actions=np.array([action], dtype=np.int64),
        reward=np.array([reward], dtype=np.float32),
        next_obs=_cell(next_cell),
        terminated=np.array([terminated], dtype=bool),
        active=np.array([True], dtype=bool),
        truncated=truncated,
    )


def _sample_transition(spec: dict[str, Any]) -> Transition:
    return Transition(
        obs=_array(spec["obs"]),
        actions=_array(spec["actions"]),
        reward=_array(spec["reward"]),
        next_obs=_array(spec["next_obs"]),
        terminated=_array(spec["terminated"]),
        active=_array(spec["active"]),
        truncated=bool(spec["truncated"]),
    )


def _params(lr: float | None = None, gamma: float | None = None) -> AgentParams:
    raw = _load(PARAMS_SAMPLE)
    if lr is not None:
        raw["lr"] = lr
    if gamma is not None:
        raw["gamma"] = gamma
    return AgentParams(**raw)


def _exploration() -> Exploration:
    return Exploration(**_load(EXPLORATION_SAMPLE))


@pytest.fixture
def tc12() -> tuple[dict[str, Any], dict[str, Any]]:
    return _load(TC12 / "input.json"), _load(TC12 / "expected.json")


@pytest.fixture
def tc13() -> tuple[dict[str, Any], dict[str, Any]]:
    return _load(TC13 / "input.json"), _load(TC13 / "expected.json")


def _tc12_agent(inputs: dict[str, Any]) -> TabularAgent:
    return TabularAgent(
        N_ACTIONS,
        _params(lr=inputs["lr"], gamma=inputs["gamma"]),
        _exploration(),
        seed=0,
    )


def _tc12_transition(step: dict[str, Any], *, truncated: bool = False) -> Transition:
    return _transition(
        step["obs_cell"],
        step["action"],
        step["reward"],
        step["next_cell"],
        terminated=step["terminated"],
        truncated=truncated,
    )


@pytest.mark.intent
def test_tc12_terminal_update_then_bootstrapped_update(
    tc12: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, expected = tc12
    agent = _tc12_agent(inputs)
    first, second = inputs["transitions"]

    agent.learn(_tc12_transition(first))
    after_1 = expected["after_1"]
    assert agent.value(_cell(after_1["cell"]), after_1["action"]) == pytest.approx(
        after_1["value"], abs=expected["tol"]
    )

    agent.learn(_tc12_transition(second))
    after_2 = expected["after_2"]
    assert agent.value(_cell(after_2["cell"]), after_2["action"]) == pytest.approx(
        after_2["value"], abs=expected["tol"]
    )
    # The first value is untouched by the second update.
    assert agent.value(_cell(after_1["cell"]), after_1["action"]) == pytest.approx(
        after_1["value"], abs=expected["tol"]
    )


@pytest.mark.intent
def test_tc12_truncated_step_still_bootstraps(
    tc12: tuple[dict[str, Any], dict[str, Any]],
) -> None:
    inputs, expected = tc12
    agent = _tc12_agent(inputs)
    first, second = inputs["transitions"]
    agent.learn(_tc12_transition(first))
    agent.learn(_tc12_transition(second, truncated=True))
    after_2 = expected["after_2"]
    assert agent.value(_cell(after_2["cell"]), after_2["action"]) == pytest.approx(
        after_2["value"], abs=expected["tol"]
    )


@pytest.mark.intent
def test_unlearned_pairs_read_zero(tc12: tuple[dict[str, Any], dict[str, Any]]) -> None:
    inputs, _ = tc12
    agent = _tc12_agent(inputs)
    for cell in range(N_CELLS):
        for action in range(N_ACTIONS):
            assert agent.value(_cell(cell), action) == 0.0
    agent.learn(_tc12_transition(inputs["transitions"][0]))
    first = inputs["transitions"][0]
    other_action = 1 - first["action"]
    assert agent.value(_cell(first["obs_cell"]), other_action) == 0.0
    assert agent.value(_cell(first["obs_cell"] - 1), first["action"]) == 0.0


@pytest.mark.intent
def test_tc13_exploration_rate_decays_linearly_to_floor(
    tc13: tuple[dict[str, Any], dict[str, Any]],
) -> None:
