            expected["rate"][str(step)], abs=expected["tol"]
        )


@pytest.mark.intent
def test_exploration_rate_rejects_negative_step() -> None:
    agent = TabularAgent(N_ACTIONS, _params(), _exploration(), seed=0)
    with pytest.raises(ValueError, match=r"(?i)(step|negative)"):
        agent.exploration_rate(-1)


def _greedy_on_cell_zero(agent: TabularAgent) -> int:
    # Reward action 0 at cell 0 so the best-valued action there is 0, not "right".
    agent.learn(_transition(0, 0, 1.0, 1, terminated=True))
    assert agent.value(_cell(0), 0) > agent.value(_cell(0), 1)
    return 0


@pytest.mark.intent
