    # Defaults: start=1.0 over 50,000 steps, so the rate is ~1.0 after one learn call.
    agent = TabularAgent(N_ACTIONS, _params(), _exploration(), seed=0, explore_enabled=False)
    best = _greedy_on_cell_zero(agent)
    assert agent.exploration_rate(1) > 0.99
    actions = [int(agent.act(_cell(0), explore=True)[0]) for _ in range(1_000)]
    assert actions == [best] * 1_000


@pytest.mark.intent
def test_explore_false_takes_best_valued_action() -> None:
    agent = TabularAgent(N_ACTIONS, _params(), _exploration(), seed=0)
    best = _greedy_on_cell_zero(agent)
    actions = [int(agent.act(_cell(0), explore=False)[0]) for _ in range(200)]
    assert actions == [best] * 200


@pytest.mark.intent
def test_explore_true_uses_rate_at_learn_call_count() -> None:
    # start=1.0 -> end=0.0 at one step: random before any learn, greedy after one.
    exploration = Exploration(start=1.0, end=0.0, decay_steps=1)
    fresh = TabularAgent(N_ACTIONS, _params(), exploration, seed=0)
    before = {int(fresh.act(_cell(0), explore=True)[0]) for _ in range(200)}
    assert before == {0, 1}

    agent = TabularAgent(N_ACTIONS, _params(), exploration, seed=0)
    best = _greedy_on_cell_zero(agent)
    after = [int(agent.act(_cell(0), explore=True)[0]) for _ in range(200)]
    assert after == [best] * 200


@pytest.mark.intent
def test_contract_replay_of_five_act_learn_calls() -> None:
    sample = _load(TABULAR_SAMPLE)
    team = sample["team"]
    n_actions = team["actions"]["n"]
    agent = TabularAgent(n_actions, _params(), _exploration(), seed=0)
    acts = 0
    learns = 0
    for call in sample["calls"]:
        if call["method"] == "act":
            out = agent.act(_array(call["obs"]), explore=call["explore"])
            returns = call["returns"]
            assert out.shape == tuple(returns["shape"])
            assert np.issubdtype(out.dtype, np.integer)
            assert 0 <= int(out[0]) < n_actions
            acts += 1
        else:
            agent.learn(_sample_transition(call["transition"]))
            learns += 1
    assert (acts, learns) == (5, 5)
    # Every replayed reward is 0 and nothing downstream was learned, so all values stay 0.
    for call in sample["calls"]:
        if call["method"] == "learn":
            t = call["transition"]
            obs = _array(t["obs"])
            action = int(_array(t["actions"])[0])
            assert agent.value(obs, action) == 0.0


@pytest.mark.intent
def test_save_then_load_round_trips_values_and_greedy_acts(tmp_path: Path) -> None:
    agent = TabularAgent(N_ACTIONS, _params(), _exploration(), seed=0)
    best = _greedy_on_cell_zero(agent)
    agent.learn(_transition(7, 1, 0.0, 0, terminated=False))
    path = tmp_path / "tabular.npz"
    agent.save(path)
    with np.load(path) as checkpoint:
        assert len(checkpoint.files) > 0

    restored = TabularAgent(N_ACTIONS, _params(), _exploration(), seed=1)
    restored.load(path)
    for cell in (0, 7):
        for action in range(N_ACTIONS):
            assert restored.value(_cell(cell), action) == agent.value(_cell(cell), action)
    assert int(restored.act(_cell(0), explore=False)[0]) == best
    for cell in range(N_CELLS):
        assert np.array_equal(
            restored.act(_cell(cell), explore=False), agent.act(_cell(cell), explore=False)
        )

